window.__calls = 0;
async function fetchWin(a,b,depth){
  const q = `last_event_time BETWEEN TIMESTAMP "${new Date(a).toISOString().replace('.000','')}" AND TIMESTAMP "${new Date(b).toISOString().replace('.000','')}"`;
  const r = await fetch('https://api.sendgrid.com/v3/messages?limit=1000&query='+encodeURIComponent(q),{credentials:'include'});
  window.__calls++;
  if(r.status!==200) return ['ERR',r.status,await r.text()];
  const j = await r.json();
  const msgs = j.messages||[];
  if(msgs.length>=1000 && depth<6){
    const mid = a + Math.floor((b-a)/2);
    const x = await fetchWin(a,mid,depth+1); const y = await fetchWin(mid+1000,b,depth+1);
    return [x,y];
  }
  for(const m of msgs) window.__rows[m.msg_id] = m;
  return msgs.length;
}
const res = await fetchWin(Date.parse('2026-11-13T00:00:00Z'), Date.parse('2026-11-16T12:00:00Z'), 0);
({res, calls: window.__calls, unique: Object.keys(window.__rows).length})

